const u={"p1-eco-t2":[{title:"Créer et mesurer la richesse",context:"Une entreprise a une production de 300 000 € et des consommations intermédiaires de 110 000 €. Par ailleurs, le PIB du pays passe de 2 500 milliards € à 2 550 milliards €.",questions:[{q:"Calcule la valeur ajoutée de l’entreprise (en €).",a:"190000",num:!0,e:"VA = production − consommations intermédiaires = 300 000 − 110 000 = 190 000 €."},{q:"Calcule le taux de croissance du PIB (en %).",a:"2",num:!0,e:"Taux = (2 550 − 2 500) / 2 500 = 50 / 2 500 = 2 %."}]}],"p1-eco-t5":[{title:"Le marché et l’élasticité",context:"Sur le marché d'un bien, le prix augmente de 5 %. On observe alors une baisse des quantités demandées de 15 %.",questions:[{q:"Calcule l'élasticité-prix de la demande.",a:"-3",num:!0,alt:["−3"],e:"e = variation % des quantités / variation % du prix = −15 / +5 = −3."},{q:"La demande est-elle « élastique » ou « inélastique » ?",a:"élastique",alt:["elastique"],e:"|e| = 3 > 1 : la demande est très sensible au prix, donc élastique."}]}]},f=Object.freeze(Object.defineProperty({__proto__:null,default:u},Symbol.toStringTag,{value:"Module"})),l={"p1-eco-t1":[["Besoin","Sensation de manque que l’on cherche à satisfaire."],["Bien / service","Produit matériel / prestation immatérielle satisfaisant un besoin."],["Rareté","Ressources limitées face à des besoins illimités."],["Agent économique","Acteur qui décide et agit (ménage, entreprise, État)."],["Coût d’opportunité","Valeur de la meilleure option à laquelle on renonce en choisissant."],["Circuit économique","Représentation des flux entre les agents économiques."]],"p1-eco-t2":[["Production","Création de biens et services par les agents économiques."],["Valeur ajoutée","Richesse créée = production − consommations intermédiaires."],["PIB","Somme des valeurs ajoutées produites dans un pays sur un an."],["Facteurs de production","Moyens utilisés pour produire : travail et capital."],["Productivité","Efficacité de la production : production / facteurs utilisés."],["Croissance économique","Augmentation durable de la production (PIB)."]],"p1-eco-t3":[["Revenu primaire","Revenu tiré de la participation à la production (salaires, profits)."],["Revenu de transfert","Revenu versé sans contrepartie de travail (allocations, retraites)."],["Redistribution","Prélèvements et prestations réduisant les inégalités."],["Revenu disponible","Revenu restant après impôts et prestations, destiné à la consommation/épargne."],["Prélèvements obligatoires","Impôts et cotisations versés aux administrations."],["Inégalités","Différences de revenus, de patrimoine ou de conditions de vie."]],"p1-eco-t4":[["Financement","Recherche des fonds nécessaires à l’activité et à l’investissement."],["Autofinancement","Financement par les ressources propres de l’agent."],["Crédit","Prêt d’argent remboursé avec intérêts."],["Marché financier","Lieu d’émission et d’échange des actions et obligations."],["Action","Titre de propriété d’une part d’entreprise, donnant droit à un dividende."],["Obligation","Titre de créance : prêt à une entreprise ou à l’État, rémunéré par un intérêt."],["Taux d’intérêt","Prix du crédit ou rémunération de l’épargne."]],"p1-eco-t5":[["Marché","Lieu de rencontre de l’offre et de la demande."],["Offre","Quantité qu’un vendeur propose à un prix donné."],["Demande","Quantité que les acheteurs souhaitent acquérir à un prix donné."],["Prix d’équilibre","Prix qui égalise les quantités offertes et demandées."],["Concurrence pure et parfaite","Marché idéal (atomicité, homogénéité, transparence, libre entrée, mobilité)."],["Monopole","Marché où un seul vendeur fait face à de nombreux acheteurs."],["Oligopole","Marché dominé par un petit nombre de vendeurs."]]},b=Object.freeze(Object.defineProperty({__proto__:null,default:l},Symbol.toStringTag,{value:"Module"})),c={"p1-eco-t4":{sections:[{h:"💶 Exemple traité — financer une machine : interne, direct ou indirect",group:"cas",blocks:[{t:"example",h:"Cas",c:"Une PME veut acheter une nouvelle machine à 100 000 €. Comment financer cet investissement ?"},{t:"list",c:["**Financement interne** (autofinancement) : utiliser ses bénéfices mis en réserve → pas de dette, mais épuise la trésorerie.","**Financement externe direct** : émettre des actions/obligations (surtout pour les grandes entreprises) → se financer sur les marchés.","**Financement externe indirect** : emprunter auprès d’une **banque** (crédit) → solution la plus courante pour une PME, mais coût des intérêts."]},{t:"tip",h:"À retenir",c:"Direct = passer par les marchés financiers ; indirect = passer par une banque (intermédiaire)."}]}]},"p1-eco-t1":{sections:[{h:"💶 Exemple — un budget de 50 € : rareté et coût d’opportunité",group:"cas",blocks:[{t:"example",h:"Situation",c:"Avec un budget de 50 €, un étudiant hésite entre des livres et des sorties."},{t:"list",c:["**Rareté** : les ressources (ici l’argent) sont limitées face à des besoins illimités.","**Choix & coût d’opportunité** : choisir les livres, c’est renoncer aux sorties (ce à quoi on renonce = coût d’opportunité).","**Les agents** (ménages, entreprises, État) font tous des choix sous contrainte de ressources."]},{t:"tip",h:"Idée fondatrice",c:"L’économie étudie comment des agents font des **choix** face à la **rareté**."}]}]},"p1-eco-t2":{sections:[{h:"💶 Exemple chiffré — une boulangerie : calculer la valeur ajoutée",group:"cas",blocks:[{t:"example",h:"Énoncé",c:"Une boulangerie produit pour 300 000 € de pain sur l’année. Elle a acheté pour 110 000 € de farine, d’énergie et de fournitures."},{t:"list",c:["**Valeur ajoutée** = production − consommations intermédiaires = 300 000 − 110 000 = **190 000 €**.","La VA mesure la **richesse réellement créée** (pas le chiffre d’affaires).","La somme des VA de toutes les entreprises d’un pays = le **PIB**."]},{t:"tip",h:"Piège",c:"Ne confonds pas production (300 000) et valeur ajoutée (190 000) : on retire ce qui a été acheté à d’autres (les consommations intermédiaires)."}]}]},"p1-eco-t3":{sections:[{h:"💶 Exemple — un salarié à 1 800 € : revenus primaires et redistribution",group:"cas",blocks:[{t:"example",h:"Situation",c:"Un salarié gagne 1 800 € net, touche des allocations et paie des impôts."},{t:"list",c:["**Revenus primaires** : issus de la production — du travail (salaire) ou du capital (loyers, dividendes, intérêts).","**Redistribution** : l’État prélève (impôts, cotisations) et verse des **prestations** (allocations, retraites) → revenu disponible.","Objectif : réduire les **inégalités** et couvrir les risques sociaux."]},{t:"tip",h:"Formule",c:"Revenu disponible = revenus primaires + prestations reçues − prélèvements obligatoires."}]}]},"p1-eco-t5":{sections:[{h:"💶 Exemple — une baisse de prix : demande, offre et prix d’équilibre",group:"cas",blocks:[{t:"example",h:"Situation",c:"Sur un marché, quand le prix d’un produit baisse, les acheteurs sont plus nombreux mais les vendeurs moins motivés."},{t:"list",c:["**Demande** : elle **augmente** quand le prix baisse (courbe décroissante).","**Offre** : elle **augmente** quand le prix monte (courbe croissante).","**Prix d’équilibre** : là où offre = demande. Ce n’est pas l’État qui le fixe (marché concurrentiel).","**Élasticité** : mesure la sensibilité de la demande au prix (garde le signe, raisonne en %)."]},{t:"tip",h:"Voir le schéma",c:"Le « Schéma du thème » (offre/demande) illustre exactement ce point d’équilibre."}]}]}},h=Object.freeze(Object.defineProperty({__proto__:null,default:c},Symbol.toStringTag,{value:"Module"})),d={"p1-eco-t5":{id:"p1-eco-t5-doc",type:"doc",title:"Étude de documents — Le paradoxe de l’eau et du diamant",icon:"📑",intro:"Un grand classique de l’économie : pourquoi l’eau, vitale, coûte-t-elle si peu, alors que le diamant, inutile à la survie, coûte si cher ? Lis les documents puis réponds.",documents:[{id:1,title:"Document 1 — L’énigme d’Adam Smith",text:"« Rien n’est plus utile que l’eau : mais elle ne peut presque rien acheter ; à peine peut-on avoir quoi que ce soit en échange. Un diamant, au contraire, n’a presque aucune valeur d’usage ; mais on peut souvent obtenir en échange une très grande quantité d’autres biens. »",source:"D’après A. Smith, Recherches sur la nature et les causes de la richesse des nations, 1776."},{id:2,title:"Document 2 — Deux sortes de valeur",text:`Les économistes distinguent deux valeurs pour un bien :
• la **valeur d’usage** : l’utilité qu’il procure, ce à quoi il sert (l’eau permet de vivre) ;
• la **valeur d’échange** : ce que l’on peut obtenir contre lui sur le marché, c’est-à-dire son **prix**.
Un bien peut avoir une forte valeur d’usage et une faible valeur d’échange, et inversement.`},{id:3,title:"Document 3 — Le rôle de la rareté",text:"Sur un marché, le prix résulte de la confrontation de l’**offre** et de la **demande**. L’eau est très **abondante** (offre élevée) : son prix est bas. Le diamant est **rare** (offre limitée) alors que beaucoup le désirent : son prix est élevé. La **rareté relative** d’un bien pèse donc fortement sur sa valeur d’échange."},{id:4,title:"Document 4 — L’utilité marginale (résolution du paradoxe)",text:"À partir de 1870, les économistes montrent que la valeur ne dépend pas de l’utilité totale d’un bien, mais de son **utilité marginale** : l’utilité de la **dernière unité** consommée. L’eau étant abondante, la dernière unité consommée (arroser, laver) apporte peu : son utilité marginale — donc son prix — est faible. Le diamant étant rare, chaque unité supplémentaire a une forte utilité marginale : son prix est élevé."},{id:5,title:"Document 5 — Un verre d’eau dans le désert",text:"Le contexte change tout. En ville, l’eau du robinet est quasi gratuite. En plein désert, un voyageur assoiffé paierait très cher un simple verre d’eau : l’eau y est **rare** et son **utilité marginale** immédiate est énorme. La valeur d’échange d’un même bien dépend donc de sa rareté dans une situation donnée."}],questions:[{doc:1,q:"Selon Adam Smith, l’eau possède surtout une grande…",choices:["valeur d’usage","valeur d’échange","rareté","utilité marginale"],answer:0,explain:"L’eau est très utile (forte valeur d’usage) mais « n’achète presque rien » (faible valeur d’échange)."},{doc:2,q:"La valeur d’échange d’un bien correspond à…",choices:["ce que l’on obtient contre lui : son prix","l’usage auquel il sert","sa durée de vie","son poids"],answer:0,explain:"Valeur d’échange = prix sur le marché ; valeur d’usage = utilité."},{doc:3,q:"D’après le document 3, le prix élevé du diamant s’explique d’abord par…",choices:["sa rareté (offre limitée, forte demande)","son utilité vitale","son abondance","son faible coût de transport"],answer:0,explain:"Le prix naît de l’offre et de la demande ; la rareté relative du diamant tire son prix vers le haut."},{doc:4,q:"L’utilité marginale est l’utilité…",choices:["de la dernière unité consommée","de toutes les unités additionnées","du premier acheteur","du producteur"],answer:0,explain:"C’est l’apport de la dernière unité consommée — la clé de la résolution du paradoxe."},{doc:4,q:"Pourquoi l’eau a-t-elle une faible valeur d’échange selon le document 4 ?",choices:["son abondance rend l’utilité marginale de la dernière unité faible","elle est inutile","personne n’en veut","elle est interdite à la vente"],answer:0,explain:"Abondante, la dernière unité consommée apporte peu : utilité marginale faible → prix bas."},{doc:[1,2],type:"redac",q:"Explique, avec tes mots, en quoi consiste le « paradoxe de l’eau et du diamant ».",answer:"Le paradoxe oppose deux biens : l’eau, indispensable à la vie, a une très grande **valeur d’usage** mais une faible **valeur d’échange** (elle coûte presque rien) ; le diamant, quasi inutile à la survie, a une faible valeur d’usage mais une très forte valeur d’échange (il coûte cher). Autrement dit, l’utilité d’un bien ne détermine pas directement son prix."},{doc:[3,4],type:"redac",q:"Comment la rareté et l’utilité marginale permettent-elles de résoudre ce paradoxe ?",answer:"Le prix dépend de la **rareté** (offre/demande) et de l’**utilité marginale** (utilité de la dernière unité). L’eau est abondante : l’utilité de la dernière unité consommée est faible, donc son prix est bas. Le diamant est rare : chaque unité a une forte utilité marginale, donc son prix est élevé. Ce n’est donc pas l’utilité totale, mais l’utilité de la dernière unité (liée à la rareté), qui fixe la valeur d’échange."},{doc:5,type:"redac",q:"En plein désert, un verre d’eau vaut très cher. Explique ce changement à l’aide des notions du dossier.",answer:"Dans le désert, l’eau devient **rare** et le besoin est vital : l’**utilité marginale** du verre d’eau est énorme et l’offre très limitée. Sa **valeur d’échange** (son prix) grimpe donc fortement, alors qu’en ville, abondante, elle est quasi gratuite. Un même bien change de valeur selon sa rareté dans le contexte."}]},"p1-eco-t1":{id:"p1-eco-t1-doc",type:"doc",title:"Étude de documents — Rareté, choix et agents économiques",icon:"📑",intro:"Pourquoi doit-on faire des choix, et qui sont les acteurs de l’économie ? Lis les documents puis réponds.",documents:[{id:1,title:"Document 1 — La rareté et les choix",text:"Les **besoins** des individus sont illimités, mais les **ressources** pour les satisfaire sont **limitées** : c’est la **rareté**. Elle oblige à faire des **choix** et à renoncer à d’autres emplois des ressources. L’économie répond à trois grandes questions : **que produire ?**, **comment produire ?**, **pour qui produire ?**."},{id:2,title:"Document 2 — Le coût d’opportunité",text:"Choisir, c’est renoncer. Le **coût d’opportunité** d’un choix est la valeur de la **meilleure option à laquelle on renonce**. Exemple : consacrer une soirée à réviser, c’est renoncer à la soirée de loisir que l’on aurait pu passer à la place."},{id:3,title:"Document 3 — Les agents économiques",text:"L’économie est animée par des **agents** aux rôles différents : les **ménages** (consomment, épargnent, offrent du travail), les **entreprises** (produisent des biens et services), les **administrations publiques** (fournissent des services non marchands, prélèvent, redistribuent), les **banques** (financent), et le **reste du monde** (échanges extérieurs)."},{id:4,title:"Document 4 — Le circuit économique",text:"Les agents sont reliés par un **circuit** : à un **flux réel** (biens, services, travail) correspond un **flux monétaire** en sens inverse. Ainsi, un ménage fournit du travail à une entreprise (flux réel) et reçoit un salaire (flux monétaire) ; il achète des biens (flux réel) et paie un prix (flux monétaire)."}],questions:[{doc:1,q:"La rareté vient du fait que les besoins sont… et les ressources…",choices:["illimités / limitées","limités / illimitées","nuls / infinies","égaux / égales"],answer:0,explain:"Besoins illimités face à des ressources limitées → nécessité de choisir."},{doc:1,q:"« Pour qui produire ? » est…",choices:["l’une des trois grandes questions économiques","une loi fiscale","un agent économique","un flux monétaire"],answer:0,explain:"Que / comment / pour qui produire."},{doc:2,q:"Le coût d’opportunité d’un choix est…",choices:["la valeur de la meilleure option à laquelle on renonce","le prix d’achat en euros","un impôt","un salaire"],answer:0,explain:"Choisir, c’est renoncer : le coût est l’option abandonnée."},{doc:3,q:"Les administrations publiques ont notamment pour rôle de…",choices:["fournir des services non marchands et redistribuer","produire uniquement pour l’export","fixer les prix de tous les biens","remplacer les ménages"],answer:0,explain:"Services non marchands, prélèvements, redistribution."},{doc:4,q:"Dans le circuit économique, à un flux réel correspond…",choices:["un flux monétaire en sens inverse","un autre flux réel identique","aucun échange","un impôt uniquement"],answer:0,explain:"Flux réel (travail, biens) ↔ flux monétaire (salaire, prix)."},{doc:2,type:"redac",q:"Explique la notion de coût d’opportunité à l’aide d’un exemple.",answer:"Le **coût d’opportunité** d’un choix est la valeur de la **meilleure option sacrifiée**. Comme les ressources (temps, argent) sont **rares**, choisir une chose, c’est **renoncer** à une autre. Exemple : un élève qui passe sa soirée à réviser renonce à la soirée entre amis qu’il aurait pu vivre à la place ; cette soirée perdue est le coût d’opportunité de sa révision."},{doc:3,type:"redac",q:"Cite trois agents économiques et précise leur rôle principal.",answer:"Les **ménages** consomment, épargnent et offrent leur travail. Les **entreprises** produisent des biens et des services marchands. Les **administrations publiques** fournissent des services non marchands, prélèvent des impôts et redistribuent les revenus. On peut ajouter les **banques** (qui financent) et le **reste du monde** (échanges extérieurs)."},{doc:4,type:"redac",q:"À l’aide du circuit économique, montre la relation entre un ménage et une entreprise.",answer:"Le **circuit économique** relie les agents par des flux de sens opposés. Un **ménage** fournit son **travail** à l’**entreprise** (flux réel) et reçoit en retour un **salaire** (flux monétaire). Avec ce revenu, il **achète** des biens et services produits par l’entreprise (flux réel) et paie un **prix** (flux monétaire). À chaque flux réel correspond donc un flux monétaire inverse."}]},"p1-eco-t2":{id:"p1-eco-t2-doc",type:"doc",title:"Étude de documents — Créer et mesurer la richesse",icon:"📑",intro:"Comment mesure-t-on la richesse réellement créée par une entreprise et par un pays ? Lis les documents puis réponds.",documents:[{id:1,title:"Document 1 — Production marchande et non marchande",text:"La **production marchande** est vendue sur un marché à un prix couvrant les coûts (une baguette, une coupe de cheveux). La **production non marchande** est fournie gratuitement ou quasi gratuitement, financée par l’impôt (l’école publique, la justice). La production combine deux **facteurs** : le **travail** et le **capital**."},{id:2,title:"Document 2 — La valeur ajoutée",text:"La richesse réellement créée par une entreprise se mesure par sa **valeur ajoutée** : la valeur de sa **production** diminuée des **consommations intermédiaires** (biens et services achetés à d’autres et détruits dans la production).",source:"VA = Production − Consommations intermédiaires"},{id:3,title:"Document 3 — Le PIB et la croissance",text:"Le **PIB** (produit intérieur brut) mesure la richesse créée dans un pays sur une année : c’est la **somme des valeurs ajoutées**. La **croissance économique** est l’augmentation durable du PIB, mesurée par un **taux de croissance** d’une année sur l’autre."},{id:4,title:"Document 4 — La boulangerie de M. Léon",text:"Sur un mois, la boulangerie de M. Léon vend pour **20 000 €** de pains et viennoiseries. Pour produire, elle a acheté pour **7 000 €** de farine, d’œufs, d’électricité et d’emballages (consommations intermédiaires)."}],questions:[{doc:1,q:"L’école publique gratuite relève de la production…",choices:["non marchande","marchande","industrielle exportée","intermédiaire"],answer:0,explain:"Fournie gratuitement, financée par l’impôt."},{doc:1,q:"Les deux facteurs de production sont…",choices:["le travail et le capital","l’offre et la demande","l’impôt et l’épargne","le prix et le salaire"],answer:0,explain:"Travail + capital."},{doc:2,q:"La valeur ajoutée se calcule…",choices:["production − consommations intermédiaires","production + salaires","chiffre d’affaires + impôts","production × prix"],answer:0,explain:"VA = production − consommations intermédiaires."},{doc:3,q:"Le PIB d’un pays est…",choices:["la somme des valeurs ajoutées","le total des salaires seulement","la somme des importations","le montant des impôts"],answer:0,explain:"PIB = somme des VA."},{doc:[2,4],q:"La valeur ajoutée de la boulangerie de M. Léon est de…",choices:["13 000 €","20 000 €","7 000 €","27 000 €"],answer:0,explain:"VA = 20 000 − 7 000 = 13 000 €."},{doc:1,type:"redac",q:"Distingue production marchande et production non marchande, avec un exemple de chacune.",answer:"La production **marchande** est **vendue sur un marché** à un prix destiné à couvrir les coûts : par exemple une baguette de pain ou une coupe de cheveux. La production **non marchande** est fournie **gratuitement ou quasi gratuitement** et financée par l’**impôt** : par exemple l’enseignement public ou la justice. Les deux créent de la richesse mais ne se vendent pas de la même façon."},{doc:[2,4],type:"redac",q:"Calcule la valeur ajoutée de la boulangerie et explique ce qu’elle représente.",answer:"La **valeur ajoutée** = **production − consommations intermédiaires** = 20 000 − 7 000 = **13 000 €**. Elle représente la **richesse réellement créée** par la boulangerie : ce n’est pas tout le chiffre d’affaires (20 000 €), car une partie (7 000 €) correspond à des biens achetés à d’autres et « consommés » dans la production. La VA servira notamment à rémunérer le travail et le capital."},{doc:3,type:"redac",q:"Qu’est-ce que la croissance économique et comment la mesure-t-on ?",answer:"La **croissance économique** est l’**augmentation durable de la production** d’un pays. On la mesure par l’évolution du **PIB** (somme des valeurs ajoutées) d’une année sur l’autre : le **taux de croissance** indique de combien de pour cent le PIB a augmenté. Une croissance positive signifie que le pays a créé plus de richesses que l’année précédente."}]},"p1-eco-t3":{id:"p1-eco-t3-doc",type:"doc",title:"Étude de documents — La répartition des revenus",icon:"📑",intro:"Comment la richesse créée est-elle partagée, puis corrigée par l’État ? Lis les documents puis réponds.",documents:[{id:1,title:"Document 1 — La répartition primaire",text:"La valeur ajoutée est d’abord partagée entre ceux qui ont participé à la production : c’est la **répartition primaire**. On distingue les **revenus du travail** (salaires), les **revenus du capital** (intérêts, loyers, dividendes) et les **revenus mixtes** (indépendants, qui rémunèrent à la fois travail et capital)."},{id:2,title:"Document 2 — La redistribution",text:"L’État corrige ensuite cette répartition pour réduire les inégalités : c’est la **redistribution**. Il opère des **prélèvements obligatoires** (impôts, cotisations sociales) et verse des **revenus de transfert** (allocations, retraites, aides). On obtient alors le **revenu disponible** des ménages.",source:"Revenu disponible = Revenus primaires − Prélèvements obligatoires + Revenus de transfert"},{id:3,title:"Document 3 — Consommer ou épargner",text:"Avec son revenu disponible, le ménage arbitre entre **consommer** (dépenser) et **épargner** (mettre de côté). Le **taux d’épargne** = épargne / revenu disponible. Notions liées : le **pouvoir d’achat** (ce que le revenu permet réellement d’acheter compte tenu des prix) et le **patrimoine** (accumulation de l’épargne)."},{id:4,title:"Document 4 — Le budget de la famille Diallo",text:"La famille Diallo perçoit **2 800 €** de revenus primaires (salaires). Elle paie **600 €** de prélèvements obligatoires et reçoit **200 €** d’allocations. Ce mois-ci, elle consomme **2 100 €**."}],questions:[{doc:1,q:"Les salaires sont des revenus…",choices:["du travail","du capital","mixtes","de transfert"],answer:0,explain:"Travail = salaires ; capital = intérêts, loyers, dividendes."},{doc:2,q:"La redistribution consiste à…",choices:["prélever des prélèvements obligatoires et verser des revenus de transfert","produire des biens","fixer les prix","créer de la monnaie"],answer:0,explain:"Elle corrige la répartition primaire."},{doc:2,q:"La formule du revenu disponible est…",choices:["revenus primaires − prélèvements obligatoires + revenus de transfert","revenus primaires + prélèvements obligatoires","salaires − TVA","consommation + épargne"],answer:0,explain:"On retranche les prélèvements et on ajoute les transferts."},{doc:3,q:"Le taux d’épargne se calcule…",choices:["épargne / revenu disponible","consommation / revenu","revenu / dépenses","épargne × prix"],answer:0,explain:"Taux d’épargne = épargne / revenu disponible."},{doc:[2,4],q:"Le revenu disponible de la famille Diallo est de…",choices:["2 400 €","2 800 €","3 600 €","2 000 €"],answer:0,explain:"2 800 − 600 + 200 = 2 400 €."},{doc:1,type:"redac",q:"Présente les trois types de revenus de la répartition primaire.",answer:"La **répartition primaire** partage la valeur ajoutée entre : les **revenus du travail** (les **salaires** des salariés) ; les **revenus du capital** (les **intérêts, loyers et dividendes** perçus par ceux qui détiennent du capital) ; et les **revenus mixtes** (ceux des **indépendants**, qui rémunèrent à la fois leur travail et leur capital)."},{doc:[2,4],type:"redac",q:"Calcule le revenu disponible de la famille Diallo, puis son taux d’épargne.",answer:"**Revenu disponible** = revenus primaires − prélèvements obligatoires + revenus de transfert = 2 800 − 600 + 200 = **2 400 €**. L’**épargne** = revenu disponible − consommation = 2 400 − 2 100 = **300 €**. Le **taux d’épargne** = épargne / revenu disponible = 300 / 2 400 = **12,5 %**."},{doc:3,type:"redac",q:"Explique la différence entre revenu disponible et pouvoir d’achat.",answer:"Le **revenu disponible** est la somme d’argent dont dispose réellement le ménage pour consommer ou épargner (après prélèvements et transferts). Le **pouvoir d’achat** est ce que ce revenu permet **réellement d’acheter**, compte tenu du **niveau des prix** : si les prix augmentent plus vite que le revenu, le pouvoir d’achat baisse même si le revenu disponible progresse."}]},"p1-eco-t4":{id:"p1-eco-t4-doc",type:"doc",title:"Étude de documents — Le financement de l’économie",icon:"📑",intro:"Comment les agents qui ont besoin d’argent trouvent-ils leur financement ? Lis les documents puis réponds.",documents:[{id:1,title:"Document 1 — Besoin et capacité de financement",text:"Un agent a un **besoin de financement** lorsque ses dépenses (notamment d’investissement) dépassent ses ressources : il doit se financer. À l’inverse, un agent dont les ressources excèdent les dépenses a une **capacité de financement** : il peut prêter ou placer son épargne. Le système financier met en relation les deux."},{id:2,title:"Document 2 — Financement interne ou externe",text:"Une entreprise peut se financer par ses **ressources propres** : l’**autofinancement** (financement interne, à partir de ses bénéfices). Quand cela ne suffit pas, elle recourt à un **financement externe** : emprunter ou faire appel à des investisseurs."},{id:3,title:"Document 3 — Financement direct ou indirect",text:"Le financement externe prend deux formes. Le **financement direct** : l’agent se procure des fonds **directement sur les marchés financiers** en émettant des **actions** (parts de propriété) ou des **obligations** (titres de dette). Le **financement indirect** : l’agent emprunte auprès d’une **banque**, qui joue un rôle d’**intermédiaire** ; l’emprunt est remboursé avec des **intérêts**."},{id:4,title:"Document 4 — L’investissement de l’entreprise Novéo",text:"L’entreprise Novéo veut investir **500 000 €** dans une nouvelle machine. Ses bénéfices mis en réserve ne couvrent que **150 000 €**. Pour le reste, elle hésite entre émettre des titres sur les marchés financiers et solliciter un prêt auprès de sa banque."}],questions:[{doc:1,q:"Un agent dont les dépenses dépassent les ressources a…",choices:["un besoin de financement","une capacité de financement","un excédent","un patrimoine"],answer:0,explain:"Besoin de financement = dépenses > ressources."},{doc:2,q:"L’autofinancement est un financement…",choices:["interne (ressources propres)","externe direct","externe indirect","public"],answer:0,explain:"L’entreprise se finance sur ses propres bénéfices."},{doc:3,q:"Emprunter auprès d’une banque est un financement…",choices:["indirect","direct","interne","gratuit"],answer:0,explain:"La banque sert d’intermédiaire : financement indirect."},{doc:3,q:"Une action est…",choices:["une part de propriété de l’entreprise","un titre de dette","un crédit bancaire","un impôt"],answer:0,explain:"Action = propriété ; obligation = dette."},{doc:[1,4],q:"Novéo, dont l’investissement dépasse ses ressources propres, se trouve en situation de…",choices:["besoin de financement","capacité de financement","autofinancement total","épargne excédentaire"],answer:0,explain:"500 000 € à financer, 150 000 € disponibles → besoin de financement."},{doc:[1],type:"redac",q:"Distingue besoin de financement et capacité de financement.",answer:"Un agent a un **besoin de financement** quand ses **dépenses dépassent ses ressources** (par exemple une entreprise qui investit plus qu’elle ne dégage de bénéfices) : il doit trouver des fonds. Un agent a une **capacité de financement** quand ses **ressources dépassent ses dépenses** : il dispose d’une épargne qu’il peut **prêter ou placer**. Le système financier met en relation ceux qui ont un besoin et ceux qui ont une capacité."},{doc:3,type:"redac",q:"Distingue financement direct et financement indirect.",answer:"Le financement **direct** se fait **sur les marchés financiers** : l’agent se procure des fonds directement auprès des investisseurs en émettant des **actions** (parts de propriété) ou des **obligations** (titres de dette). Le financement **indirect** passe par un **intermédiaire**, la **banque**, qui accorde un **crédit** remboursé avec des **intérêts**. Dans le premier cas prêteur et emprunteur se rencontrent directement, dans le second la banque s’interpose."},{doc:[2,4],type:"redac",q:"Quelles solutions de financement s’offrent à Novéo pour son investissement ?",answer:"Novéo peut d’abord utiliser son **autofinancement** (150 000 € de bénéfices mis en réserve) : c’est un financement **interne**. Comme cela ne suffit pas (besoin de 500 000 €), elle doit recourir à un **financement externe** : soit **direct**, en émettant des **actions** ou des **obligations** sur les marchés financiers, soit **indirect**, en sollicitant un **prêt bancaire** remboursable avec intérêts. Le choix dépendra du coût et de sa volonté d’ouvrir ou non son capital."}]}},g=Object.freeze(Object.defineProperty({__proto__:null,default:d},Symbol.toStringTag,{value:"Module"})),p={"p1-eco-t1-doc":1,"p1-eco-t1-flash":0,"p1-eco-t1-qcm":2,"p1-eco-t1-vf":3,"p1-eco-t2-doc":5,"p1-eco-t2-flash":1,"p1-eco-t2-qcm":0,"p1-eco-t2-vf":2,"p1-eco-t3-doc":0,"p1-eco-t3-flash":2,"p1-eco-t3-qcm":3,"p1-eco-t3-tri":1,"p1-eco-t4-doc":0,"p1-eco-t4-flash":1,"p1-eco-t4-qcm":2,"p1-eco-t4-tri":4,"p1-eco-t5-doc":0,"p1-eco-t5-flash":2,"p1-eco-t5-qcm":1,"p1-eco-t5-vf":3},q=Object.freeze(Object.defineProperty({__proto__:null,default:p},Symbol.toStringTag,{value:"Module"})),e="p1-economie",t="Économie",n="Économie",i="📈",s="#dc2626",r="premiere",a="Produire, mesurer, répartir et financer la richesse.",o=[{id:"p1-eco-t1",name:"Thème 1 — Les grandes questions économiques",short:"Grandes questions",keywords:"besoin rareté choix coût agents économiques ménages entreprises administrations bien service utilité décroissante",intro:"Les **besoins** sont quasi illimités mais les **ressources** sont **rares** : la rareté oblige à faire des **choix**. C’est le cœur de la science économique.",cours:[{h:"Les besoins, les biens et les services",blocks:[{t:"p",c:"Un **besoin** est une sensation de manque que l’on cherche à satisfaire. On distingue les besoins **primaires** (vitaux : manger, se loger) et **secondaires** (loisirs, culture). Les besoins sont **quasi illimités** et se renouvellent sans cesse."},{t:"p",c:"Pour les satisfaire, on utilise des **biens** et des **services** :"},{t:"p",c:"Un **bien** est **matériel** : on peut le **toucher** et le **stocker**, comme un pain, un ordinateur ou une voiture. Un **service** est **immatériel** : il est **consommé au moment même où il est produit**, comme une coupe de cheveux, un cours ou un trajet en bus."},{t:"p",c:"Un bien peut être **libre** (gratuit et abondant, comme l’air) ou **économique** (rare, il a un prix). L’économie ne s’intéresse qu’aux biens **économiques**."},{t:"table",h:"Notions et définitions",head:["Notion","Définition"],rows:[["Besoin","Sensation de manque qu’on cherche à satisfaire"],["Bien","Produit matériel, qu’on peut toucher et stocker"],["Service","Prestation immatérielle, consommée au moment où elle est produite"],["Bien libre / économique","Gratuit et abondant (l’air) / rare, il a un prix"]]}]},{h:"La rareté et les choix",blocks:[{t:"p",c:"Le **problème économique** fondamental : les besoins sont **illimités** mais les **ressources** (temps, argent, matières) sont **rares**. La **rareté** est le point de départ de toute la science économique."},{t:"p",c:"Parce que les ressources sont rares, chaque agent doit **choisir** : un ménage avec un budget limité, une entreprise avec des moyens limités, l’État avec un budget contraint. **Faire de l’économie, c’est arbitrer.**"},{t:"tip",c:"Retiens la formule : « des besoins illimités, des ressources limitées → il faut **choisir** ». C’est la définition même de l’économie."}]},{h:"Le coût d’opportunité",blocks:[{t:"p",c:"Tout choix a un **coût** : le **coût d’opportunité** est la valeur de **ce à quoi on renonce** en choisissant autre chose. Choisir, c’est toujours renoncer."},{t:"example",h:"Le coût d’opportunité",c:`Avec 1 000 € d’économies, tu peux partir en voyage **ou** acheter un ordinateur. 
→ Si tu choisis le voyage, le **coût d’opportunité** est l’ordinateur auquel tu renonces. 
De même, une heure passée à travailler est une heure qu’on ne passe pas à se reposer : le temps aussi a un coût d’opportunité.`}]},{h:"L’utilité et le comportement du consommateur",blocks:[{t:"p",c:"Le **consommateur** cherche à maximiser son **utilité** : la **satisfaction** que lui procure la consommation, compte tenu de son **budget**. Il compare l’utilité qu’il retire d’un bien à son **prix**."},{t:"p",c:"L’utilité est **décroissante** : chaque unité supplémentaire d’un même bien procure **moins** de satisfaction que la précédente. Le premier verre d’eau dans le désert procure une énorme satisfaction, le dixième beaucoup moins."},{t:"warning",c:"C’est ce qui explique qu’on ne consomme pas une quantité infinie d’un même bien, même s’il est bon marché : passé un certain point, l’utilité supplémentaire devient trop faible."}]},{h:"Le producteur et le profit",blocks:[{t:"p",c:"Le **producteur** (l’entreprise) décide **quoi produire**, **comment** et **en quelle quantité**. Son objectif principal est de dégager un **profit** = recettes − coûts."},{t:"p",c:"Il combine des **facteurs de production** : le **travail** (les salariés) et le **capital** (machines, locaux). Il cherche la combinaison la plus **efficiente** (le meilleur résultat au moindre coût)."}]},{h:"Les agents économiques et les secteurs institutionnels",blocks:[{t:"p",c:"Un **agent économique** est un acteur qui prend des décisions économiques. La comptabilité nationale les regroupe en **six** grandes catégories (les **secteurs institutionnels**), selon leur **fonction principale** :"},{t:"p",c:"Les **ménages** **consomment**, **fournissent leur travail** et **épargnent**. Les **entreprises**, ou sociétés non financières, **produisent des biens et des services marchands**. Les **institutions financières**, comme les banques et les assurances, **financent l’économie** en accordant des crédits et en gérant des placements."},{t:"p",c:"Les **administrations publiques** (APU) **produisent des services non marchands** et **redistribuent** les revenus. Les **ISBLSM**, institutions sans but lucratif au service des ménages, regroupent les associations et les syndicats. Enfin, le **reste du monde** représente l’ensemble des **échanges avec l’étranger**, importations et exportations."},{t:"table",h:"Notions et définitions",head:["Notion","Définition"],rows:[["Agent économique","Acteur qui prend des décisions économiques"],["Ménages","Consomment, fournissent du travail, épargnent"],["Entreprises (SNF)","Produisent des biens et services marchands"],["Institutions financières","Financent l’économie (banques, assurances)"],["Administrations publiques (APU)","Produisent des services non marchands, redistribuent"],["ISBLSM","Institutions sans but lucratif au service des ménages (associations, syndicats)"],["Reste du monde","Échanges avec l’étranger (importations, exportations)"]]}]},{h:"Le circuit économique",blocks:[{t:"p",c:"Les agents sont **interdépendants** : ils échangent en permanence des **flux**. Le **circuit économique** représente ces échanges. Par exemple, entre ménages et entreprises :"},{t:"list",c:["les ménages fournissent du **travail** aux entreprises et reçoivent des **revenus** (salaires) ;","avec ces revenus, ils **consomment** les biens et services produits par les entreprises ;","les entreprises reçoivent ainsi des **recettes**, qui financent la production… et le cycle recommence."]},{t:"p",c:"À chaque **flux réel** (bien, service, travail) correspond un **flux monétaire** de sens inverse (paiement). Le circuit montre que l’économie est un **système** où tout est lié."}]}],essentiel:["Un **besoin** (primaire/secondaire) se satisfait par des **biens** (matériels) ou **services** (immatériels) ; un bien économique est **rare** (≠ bien libre).","Le problème économique : besoins **illimités** / ressources **rares** → il faut **choisir**.","**Coût d’opportunité** = valeur de ce à quoi on renonce en choisissant.","Le **consommateur** maximise son **utilité** (décroissante) sous contrainte de **budget** ; le **producteur** vise le **profit** (recettes − coûts) en combinant travail et capital.","Agents : **ménages, entreprises, institutions financières, administrations, reste du monde**.","Le **circuit économique** relie les agents par des **flux réels** et **monétaires** (de sens inverse)."],resources:[{kind:"video",label:"Les grandes questions économiques",note:"Vidéos — recherche YouTube",url:"https://www.youtube.com/results?search_query=grandes%20questions%20%C3%A9conomiques%20raret%C3%A9%20agents%20%C3%A9conomiques%20premi%C3%A8re%20STMG"}],games:[{id:"p1-eco-t1-qcm",type:"qcm",title:"QCM — Grandes questions",icon:"❓",questions:[{q:"Le problème économique de base vient de ce que les besoins sont illimités et les ressources…",choices:["rares","infinies","gratuites","interdites"],answer:0,explain:"La rareté oblige à faire des choix."},{q:"L’utilité procurée par la consommation est…",choices:["décroissante","toujours croissante","constante","nulle"],answer:0,explain:"Chaque unité supplémentaire procure moins de satisfaction."},{q:"Les ménages, dans le circuit économique…",choices:["consomment et fournissent du travail","produisent tous les biens","votent les lois","fixent les taux"],answer:0,explain:"Rôle des ménages : consommation et offre de travail."},{q:"Un service se distingue d’un bien car il est…",choices:["immatériel","toujours gratuit","toujours importé","stockable"],answer:0,explain:"Le service est immatériel, le bien est matériel."}]},{id:"p1-eco-t1-vf",type:"vraifaux",title:"Vrai / Faux rapide",icon:"⚡",questions:[{statement:"Tout choix économique implique un coût (renoncement).",answer:!0,explain:"Vrai : choisir, c’est renoncer."},{statement:"Les banques sont des agents qui financent l’économie.",answer:!0,explain:"Vrai : ce sont les institutions financières."},{statement:"L’utilité d’un bien augmente à chaque unité consommée.",answer:!1,explain:"Faux : l’utilité est décroissante."}]},{id:"p1-eco-t1-flash",type:"flashcard",title:"Flashcards — Bases",icon:"🃏",cards:[{front:"Rareté",back:"Ressources limitées face à des besoins illimités."},{front:"Coût (d’un choix)",back:"Ce à quoi on renonce en choisissant."},{front:"Utilité décroissante",back:"Chaque unité supplémentaire procure moins de satisfaction."},{front:"Agents économiques",back:"Ménages, entreprises, banques, administrations, reste du monde."}]}]},{id:"p1-eco-t2",name:"Thème 2 — Comment crée-t-on des richesses et comment les mesure-t-on ?",short:"Créer & mesurer la richesse",keywords:"production valeur ajoutée consommations intermédiaires PIB croissance limites facteurs travail capital productivité",intro:"Produire, c’est créer des biens et services. Pour mesurer la richesse **réellement créée**, on utilise la **valeur ajoutée**, puis le **PIB**.",cours:[{h:"Produire : production marchande et non marchande",blocks:[{t:"p",c:"**Produire**, c’est créer des **biens** et des **services** pour satisfaire des besoins. On distingue deux types de production :"},{t:"p",c:"La **production marchande** est **vendue sur un marché** à un prix qui doit **couvrir ses coûts** : une baguette, une place de cinéma. La **production non marchande** est **fournie gratuitement**, ou presque, et **financée par les impôts et les cotisations** : l’école publique, la justice, l’éclairage public."},{t:"p",c:"La production non marchande (assurée surtout par les **administrations publiques**) est essentielle mais ne se vend pas : on la mesure par son **coût** de production."},{t:"table",h:"Notions et définitions",head:["Notion","Définition"],rows:[["Produire","Créer des biens et des services pour satisfaire des besoins"],["Production marchande","Vendue sur un marché à un prix qui couvre ses coûts"],["Production non marchande","Fournie gratuitement, financée par les impôts et cotisations"]]}]},{h:"Les facteurs de production",blocks:[{t:"p",c:"Pour produire, on combine deux **facteurs de production** :"},{t:"p",c:"Le **facteur travail** correspond à la **main-d’œuvre**, c’est-à-dire aux salariés ; on le mesure en **heures travaillées** et en **qualification**. Le **facteur capital** correspond aux **moyens matériels durables** de la production : les **machines**, les **bâtiments**, les **outils**, les **logiciels**."},{t:"p",c:"On distingue le **capital fixe** (machines, bâtiments, qui durent plusieurs cycles) du **capital circulant** (matières premières, consommées dans la production). Augmenter le stock de capital, c’est **investir**."},{t:"table",h:"Notions et définitions",head:["Notion","Définition"],rows:[["Facteurs de production","Travail et capital combinés pour produire"],["Facteur travail","Main-d’œuvre (heures travaillées, qualification)"],["Facteur capital","Moyens matériels durables (machines, bâtiments, logiciels)"],["Capital fixe / circulant","Dure plusieurs cycles (machines) / consommé dans la production (matières)"],["Investir","Augmenter le stock de capital"]]}]},{h:"La productivité et le progrès technique",blocks:[{t:"p",c:"La **productivité** mesure l’**efficacité** de la production : c’est le rapport entre ce qui est produit et les moyens utilisés."},{t:"formula",c:"Productivité du travail = production / nombre d’heures (ou de travailleurs)"},{t:"p",c:"Gagner en productivité, c’est produire **plus avec autant** (ou autant avec moins). Les gains de productivité viennent surtout du **progrès technique** (nouvelles machines, automatisation, numérique) et de la **qualification** de la main-d’œuvre. C’est un moteur essentiel de la **croissance**."}]},{h:"La valeur ajoutée",blocks:[{t:"p",c:"Pour mesurer la richesse **réellement créée** par un producteur, on ne prend pas toute sa production : il faut retirer ce qu’il a acheté à d’autres pour produire (les **consommations intermédiaires** : matières, énergie, transformées ou détruites dans la production)."},{t:"formula",c:"Valeur ajoutée = valeur de la production − consommations intermédiaires"},{t:"example",h:"Calcul de la valeur ajoutée",c:`Un menuisier vend **100 €** de meubles en utilisant **30 €** de bois. 
→ VA = 100 − 30 = **70 €**. 
C’est cette VA de 70 € qui représente la richesse qu’il a vraiment créée (pas les 100 €, car 30 € existaient déjà).`}]},{h:"La répartition de la valeur ajoutée",blocks:[{t:"p",c:"La valeur ajoutée est ensuite **partagée** (répartie) entre ceux qui ont contribué à la production :"},{t:"list",c:["les **salariés** reçoivent les **salaires** (rémunération du travail) ;","l’**État** perçoit les **impôts** et cotisations ;","les **banques** perçoivent les **intérêts** (sur les prêts) ;","les **propriétaires** reçoivent les **bénéfices** ; une partie reste dans l’entreprise (**autofinancement**)."]},{t:"warning",c:"Le **partage de la valeur ajoutée** entre salaires et profits est un enjeu majeur : c’est un arbitrage sensible, source de débats sociaux (« qui doit toucher quelle part ? »)."}]},{h:"Le PIB : mesurer la richesse d’un pays",blocks:[{t:"p",c:"Le **PIB** (Produit Intérieur Brut) mesure la richesse créée dans un **pays** pendant un **an**. C’est la **somme de toutes les valeurs ajoutées** produites sur le territoire."},{t:"formula",c:"PIB = somme des valeurs ajoutées (produites sur un territoire, sur un an)"},{t:"p",c:"On additionne les VA plutôt que les productions pour **éviter de compter deux fois** la même richesse (le bois du menuisier serait compté à la fois chez le scieur et chez le menuisier)."}]},{h:"La croissance économique",blocks:[{t:"p",c:"La **croissance économique** est l’**augmentation du PIB** dans le temps. On la mesure par le **taux de croissance** (variation du PIB en %)."},{t:"p",c:"Ses moteurs : les **gains de productivité**, le **progrès technique**, l’**investissement**, l’augmentation de la population active. La croissance permet de créer des emplois et d’améliorer le niveau de vie… mais pas automatiquement de façon **équitable** ni **durable**."}]},{h:"Les limites du PIB",blocks:[{t:"p",c:"Le PIB est utile mais **imparfait** comme indicateur de richesse et de bien-être :"},{t:"list",c:["il ignore le **travail non rémunéré** (bénévolat, tâches domestiques) et l’**économie souterraine** ;","il ne dit rien des **inégalités** de répartition (un PIB élevé peut cacher de fortes inégalités) ;","il ne mesure pas le **bien-être** ni la qualité de vie ;","il **ignore les dégâts environnementaux** (une marée noire peut même faire monter le PIB via les dépenses de nettoyage !)."]},{t:"p",c:"D’autres indicateurs complètent le PIB : l’**IDH** (Indice de Développement Humain : santé, éducation, niveau de vie) et des indicateurs de **développement durable**."}]}],essentiel:["Produire = créer biens/services ; production **marchande** (vendue) vs **non marchande** (gratuite, financée par l’impôt).","Deux **facteurs de production** : **travail** + **capital** (fixe / circulant) ; investir = augmenter le capital.","La **productivité** (production / moyens) et le **progrès technique** sont les moteurs de la croissance.","**Valeur ajoutée = production − consommations intermédiaires** ; elle est **répartie** entre salariés, État, banques, propriétaires.","**PIB = somme des valeurs ajoutées** d’un territoire sur un an ; la **croissance** = hausse du PIB.","Le PIB est **limité** : ni bien-être, ni inégalités, ni environnement, ni travail non rémunéré → **IDH**, développement durable."],resources:[{kind:"video",label:"Valeur ajoutée, PIB, croissance",note:"Vidéos — recherche YouTube",url:"https://www.youtube.com/results?search_query=valeur%20ajout%C3%A9e%20PIB%20croissance%20facteurs%20de%20production%20premi%C3%A8re%20STMG%20%C3%A9conomie"}],games:[{id:"p1-eco-t2-qcm",type:"qcm",title:"QCM — Créer et mesurer la richesse",icon:"❓",questions:[{q:"La valeur ajoutée se calcule…",choices:["production − consommations intermédiaires","production + impôts","salaires + profit","CA − TVA"],answer:0,explain:"VA = valeur de la production − consommations intermédiaires."},{q:"Une boulangerie produit 300 000 € en consommant 90 000 €. Sa VA est…",choices:["210 000 €","390 000 €","90 000 €","300 000 €"],answer:0,explain:"VA = 300 000 − 90 000 = 210 000 €."},{q:"Le PIB est…",choices:["la somme des valeurs ajoutées d’un territoire sur un an","le total des salaires","le montant des impôts","le chiffre d’affaires mondial"],answer:0,explain:"Le PIB agrège les VA produites sur un territoire."},{q:"Une limite du PIB est qu’il ne mesure pas…",choices:["le bien-être ni les inégalités","la production","la croissance","les échanges"],answer:0,explain:"Il ignore bien-être, inégalités, environnement, travail non rémunéré."},{q:"Les deux facteurs de production sont…",choices:["le travail et le capital","l’offre et la demande","le prix et la quantité","l’actif et le passif"],answer:0,explain:"On combine travail (main-d’œuvre) et capital (équipements)."}]},{id:"p1-eco-t2-vf",type:"vraifaux",title:"Vrai / Faux rapide",icon:"⚡",questions:[{statement:"Le PIB est la somme des valeurs ajoutées.",answer:!0,explain:"Vrai, sur un territoire et une année."},{statement:"Le PIB mesure parfaitement le bien-être.",answer:!1,explain:"Faux : c’est un indicateur limité."},{statement:"Gagner en productivité peut être source de croissance.",answer:!0,explain:"Vrai : produire plus avec autant de facteurs."}]},{id:"p1-eco-t2-flash",type:"flashcard",title:"Flashcards — Richesse",icon:"🃏",cards:[{front:"Valeur ajoutée",back:"Production − consommations intermédiaires."},{front:"PIB",back:"Somme des valeurs ajoutées d’un territoire sur un an."},{front:"Limites du PIB",back:"N’intègre ni bien-être, ni inégalités, ni environnement."},{front:"Productivité",back:"Efficacité de la production (source de croissance)."}]}]},{id:"p1-eco-t3",name:"Thème 3 — Comment répartir les revenus et la richesse ?",short:"Répartition des revenus",keywords:"répartition primaire revenus travail capital mixtes redistribution prélèvements prestations revenu disponible consommation épargne taux d’épargne pouvoir d’achat patrimoine",intro:"La richesse créée (la VA) est **répartie**, d’abord entre ceux qui ont produit, puis **corrigée** par l’État pour réduire les inégalités.",cours:[{h:"La répartition primaire des revenus",blocks:[{t:"p",c:"La richesse créée (la **valeur ajoutée**) est d’abord partagée entre ceux qui ont **participé à la production** : c’est la **répartition primaire**, qui donne les **revenus primaires**."},{t:"p",c:"Ces revenus rémunèrent la contribution de chacun à la production, **avant** toute intervention de l’État."}]},{h:"Les revenus primaires : du travail, du capital et mixtes",blocks:[{t:"p",c:"Les **revenus du travail** rémunèrent le **facteur travail** : ce sont les **salaires** et les **traitements** des fonctionnaires. Les **revenus du capital** rémunèrent le **facteur capital** ou la **propriété** : ce sont les **intérêts**, les **loyers** et les **dividendes**."},{t:"p",c:"Les **revenus mixtes** rémunèrent **à la fois le travail et le capital** : c’est le **bénéfice des indépendants**, comme un artisan ou un médecin libéral, qui apportent leur travail et ont investi dans leur activité."},{t:"p",c:"Les revenus **mixtes** concernent les **indépendants** : leur bénéfice rémunère à la fois leur travail et le capital qu’ils ont investi — impossible de séparer les deux."},{t:"table",h:"Notions et définitions",head:["Notion","Définition"],rows:[["Revenus primaires","Revenus tirés de la participation à la production"],["Revenus du travail","Salaires, traitements"],["Revenus du capital","Intérêts, loyers, dividendes"],["Revenus mixtes","Bénéfices des indépendants : rémunèrent travail et capital"]]}]},{h:"La redistribution et le rôle de l’État",blocks:[{t:"p",c:"La répartition primaire laisse de fortes **inégalités**. L’État intervient donc pour les **corriger** : c’est la **redistribution**. Elle fonctionne en deux temps :"},{t:"list",c:["il **prélève** : les **prélèvements obligatoires** (impôts + cotisations sociales) ;","il **verse** : les **revenus de transfert** (prestations sociales : allocations familiales, retraites, aides au logement, minima sociaux)."]},{t:"p",c:"La redistribution finance aussi la **protection sociale** (maladie, chômage, vieillesse) : c’est la **solidarité** organisée entre les citoyens."}]},{h:"Le revenu disponible",blocks:[{t:"p",c:"Après la redistribution, le ménage obtient son **revenu disponible** : ce qui lui reste réellement pour **consommer** ou **épargner**."},{t:"formula",c:"Revenu disponible = Revenus primaires − Prélèvements obligatoires + Revenus de transfert"},{t:"example",h:"Calcul du revenu disponible",c:`Un ménage a 3 000 € de revenus primaires, paie 800 € de prélèvements et reçoit 200 € de prestations. 
→ Revenu disponible = 3 000 − 800 + 200 = **2 400 €**.`}]},{h:"Consommer ou épargner",blocks:[{t:"p",c:"Avec son revenu disponible, le ménage **arbitre** : **consommer** (dépenser maintenant) ou **épargner** (mettre de côté pour plus tard)."},{t:"formula",c:"Taux d’épargne = épargne / revenu disponible"},{t:"example",h:"Calcul du taux d’épargne",c:"Revenu disponible **2 500 €**, consommation **2 100 €** → épargne = 400 € → taux d’épargne = 400 / 2 500 = **16 %**."},{t:"p",c:"Le partage consommation / épargne dépend du revenu, de l’âge, de la confiance dans l’avenir : plus le revenu est élevé, plus la part épargnée tend à être grande."}]},{h:"Pouvoir d’achat et patrimoine",blocks:[{t:"p",c:"Le **pouvoir d’achat** est ce que le revenu permet **réellement d’acheter**, compte tenu des **prix**. Si les prix (inflation) augmentent plus vite que le revenu, le pouvoir d’achat **baisse**, même si le revenu en euros augmente."},{t:"p",c:"Le **patrimoine** est l’ensemble de ce que possède un ménage (logement, épargne, placements) : c’est un **stock** accumulé, à distinguer du **revenu** qui est un **flux** (ce qu’on gagne sur une période)."},{t:"warning",c:"Ne confonds pas **revenu** (un flux, ce qu’on gagne chaque mois) et **patrimoine** (un stock, ce qu’on possède). On peut avoir un gros patrimoine et un faible revenu, et inversement."}]},{h:"Inégalités et justice sociale",blocks:[{t:"p",c:"Les revenus et les patrimoines sont **inégalement répartis**. La **justice sociale** cherche à rendre cette répartition plus **équitable**, mais il existe plusieurs conceptions de ce qui est « juste »."},{t:"p",c:"La redistribution vise à réduire ces inégalités. Mais elle fait débat : trop de prélèvements peut **décourager** l’effort et l’investissement ; trop peu laisse se creuser les inégalités. C’est un **arbitrage** politique permanent entre **efficacité** et **équité**."}]}],essentiel:["Répartition **primaire** : **revenus primaires** = revenus du **travail** (salaires) + du **capital** (intérêts, loyers, dividendes) + **mixtes** (indépendants).","**Redistribution** de l’État : **prélèvements obligatoires** (impôts, cotisations) → **revenus de transfert** (prestations) ; finance la **protection sociale**.","**Revenu disponible = revenus primaires − prélèvements obligatoires + revenus de transfert**.","**Taux d’épargne = épargne / revenu disponible** ; arbitrage consommer / épargner.","**Pouvoir d’achat** = ce que le revenu permet d’acheter (selon les prix) ; **patrimoine** (stock) ≠ **revenu** (flux).","La **redistribution** réduit les **inégalités** : arbitrage entre **équité** et **efficacité** (justice sociale)."],resources:[{kind:"video",label:"Répartition et redistribution des revenus",note:"Vidéos — recherche YouTube",url:"https://www.youtube.com/results?search_query=r%C3%A9partition%20primaire%20redistribution%20revenu%20disponible%20taux%20%C3%A9pargne%20premi%C3%A8re%20STMG"}],games:[{id:"p1-eco-t3-qcm",type:"qcm",title:"QCM — Répartition des revenus",icon:"❓",questions:[{q:"Les salaires sont des revenus…",choices:["du travail","du capital","mixtes","de transfert"],answer:0,explain:"Travail = salaires ; capital = intérêts, loyers, dividendes ; mixtes = indépendants."},{q:"La redistribution consiste à…",choices:["prélever des prélèvements obligatoires et verser des revenus de transfert","produire des biens","fixer les prix","créer de la monnaie"],answer:0,explain:"Elle corrige la répartition primaire pour réduire les inégalités."},{q:"La formule du revenu disponible est…",choices:["revenus primaires − prélèvements obligatoires + revenus de transfert","revenus primaires + prélèvements obligatoires","salaires − TVA","consommation + épargne − impôts"],answer:0,explain:"Revenu disponible = revenus primaires − prélèvements obligatoires (impôts, cotisations) + revenus de transfert (prestations)."},{q:"Revenu disponible 2 500 €, consommation 2 100 €. Taux d’épargne ?",choices:["16 %","84 %","40 %","4 %"],answer:0,explain:"Épargne = 400 ; 400/2 500 = 0,16 = 16 %."}]},{id:"p1-eco-t3-tri",type:"tri",title:"Tri — Type de revenu",icon:"🗂️",instruction:"Classe chaque revenu.",categories:[{id:"trav",label:"Revenu du travail"},{id:"cap",label:"Revenu du capital"}],items:[{text:"Un salaire",cat:"trav"},{text:"Un loyer perçu",cat:"cap"},{text:"Des dividendes",cat:"cap"},{text:"Un traitement de fonctionnaire",cat:"trav"},{text:"Des intérêts d’un placement",cat:"cap"}]},{id:"p1-eco-t3-flash",type:"flashcard",title:"Flashcards — Revenus",icon:"🃏",cards:[{front:"Répartition primaire",back:"Partage de la VA en revenus primaires : travail, capital, mixtes."},{front:"Redistribution",back:"Prélèvements obligatoires + revenus de transfert pour réduire les inégalités."},{front:"Revenu disponible",back:"Revenus primaires − prélèvements obligatoires + revenus de transfert."},{front:"Pouvoir d’achat",back:"Ce que le revenu permet réellement d’acheter."}]}]},{id:"p1-eco-t4",name:"Thème 4 — Comment les agents économiques se financent-ils ?",short:"Le financement",keywords:"besoin capacité de financement direct indirect marché financier actions obligations banque crédit banque centrale taux directeurs",intro:"Certains agents dépensent plus qu’ils ne gagnent (**besoin de financement**), d’autres épargnent (**capacité de financement**). Le système financier met les deux en relation.",cours:[{h:"Besoin et capacité de financement",blocks:[{t:"p",c:"Sur une période, un agent économique peut être dans deux situations opposées selon que ses **dépenses** dépassent ou non ses **ressources** :"},{t:"p",c:"Un agent est en **besoin de financement** quand ses **dépenses dépassent ses ressources** : il doit **trouver des fonds**. C’est souvent le cas des **entreprises** et de l’**État**. Il est en **capacité de financement** quand ses **ressources dépassent ses dépenses** : il lui reste de l’**épargne à placer**, ce qui est souvent le cas des **ménages**."},{t:"p",c:"Le **système financier** a pour rôle de **mettre en relation** ceux qui ont un besoin de financement avec ceux qui ont une capacité de financement (les épargnants)."},{t:"table",h:"Notions et définitions",head:["Notion","Définition"],rows:[["Besoin de financement","Dépenses > ressources : il faut trouver des fonds (entreprises, État)"],["Capacité de financement","Ressources > dépenses : épargne à placer (ménages)"],["Système financier","Met en relation agents à besoin et agents à capacité de financement"]]}]},{h:"Financement interne et externe",blocks:[{t:"p",c:"Pour se financer, un agent (surtout une entreprise) a d’abord un choix de base :"},{t:"list",c:["le **financement interne** (**autofinancement**) : utiliser sa **propre épargne**, ses bénéfices mis en réserve — pas de dette, mais des moyens limités ;","le **financement externe** : trouver des fonds **à l’extérieur**, soit sur le **marché financier** (direct), soit auprès d’une **banque** (indirect)."]}]},{h:"Le financement direct (le marché financier)",blocks:[{t:"p",c:"Dans le financement **direct** (ou désintermédié), l’agent obtient des fonds **directement** des épargnants, sur le **marché financier** (la **Bourse**), en **émettant des titres**. Il n’y a pas d’intermédiaire qui prête son propre argent."},{t:"p",c:"La **Bourse** est le lieu (aujourd’hui électronique) où s’échangent ces titres : elle permet aux entreprises de lever des fonds et aux épargnants de placer leur argent."}]},{h:"Actions et obligations",blocks:[{t:"p",c:"Sur le marché financier, on émet deux grands types de titres, très différents :"},{t:"p",c:"L’**action** est un **titre de propriété** : elle représente une part de l’entreprise, et l’actionnaire en devient **copropriétaire**. Elle rapporte un **dividende**, dont le montant **varie** selon les résultats ; c’est un placement **risqué**, sans garantie."},{t:"p",c:"L’**obligation** est un **titre de dette** : elle correspond à un **prêt** fait à l’entreprise ou à l’État, et l’obligataire est un **créancier**. Elle rapporte un **intérêt fixé d’avance** et son **remboursement est prévu** : c’est un placement **plus sûr**."},{t:"warning",c:"Piège classique : **action = propriété**, **obligation = dette**. Acheter une action, c’est devenir **copropriétaire** ; acheter une obligation, c’est **prêter** de l’argent."},{t:"table",h:"Notions et définitions",head:["Notion","Définition"],rows:[["Action","Titre de propriété ; rapporte un dividende variable ; risqué"],["Obligation","Titre de dette ; rapporte un intérêt fixé d’avance ; plus sûr"],["Dividende","Part du bénéfice versée aux actionnaires"],["Marché financier","Marché où s’échangent actions et obligations"]]}]},{h:"Le financement indirect (les banques)",blocks:[{t:"p",c:"Dans le financement **indirect** (ou intermédié), l’agent passe par un **intermédiaire** : la **banque**. Elle **collecte** l’épargne des uns et accorde des **crédits** aux autres, remboursés **avec intérêts**."},{t:"p",c:"C’est le mode de financement le plus courant pour les **ménages** (crédit immobilier, crédit conso) et les **petites entreprises**, qui n’ont pas accès facilement à la Bourse."}]},{h:"La création monétaire",blocks:[{t:"p",c:"Fait surprenant : quand une banque accorde un **crédit**, elle **crée de la monnaie**. Elle n’a pas besoin de posséder au préalable tout l’argent prêté : elle inscrit simplement la somme sur le compte de l’emprunteur. « **Les crédits font les dépôts.** »"},{t:"p",c:"Quand le crédit est **remboursé**, cette monnaie est **détruite**. La création monétaire soutient l’activité, mais si elle est excessive, elle peut alimenter l’**inflation** (hausse des prix)."}]},{h:"La banque centrale et les taux directeurs",blocks:[{t:"p",c:"La **banque centrale** (la **BCE**, Banque Centrale Européenne, pour la zone euro) supervise les banques et pilote la **politique monétaire**. Son principal outil : les **taux directeurs**, le taux auquel les banques se refinancent auprès d’elle."},{t:"p",c:"Quand la **BCE baisse ses taux**, le crédit devient **moins cher** : les ménages et les entreprises **empruntent davantage**, ce qui **stimule l’activité**. L’objectif est alors de **relancer l’économie**."},{t:"p",c:"Quand la **BCE augmente ses taux**, le crédit devient **plus cher** : on **emprunte moins**, ce qui **freine l’activité**. L’objectif est alors de **freiner l’inflation**."},{t:"p",c:"La mission principale de la BCE est de **maintenir la stabilité des prix** (une inflation faible et maîtrisée)."},{t:"table",h:"Notions et définitions",head:["Notion","Définition"],rows:[["Banque centrale (BCE)","Supervise les banques et pilote la politique monétaire de la zone euro"],["Taux directeur","Taux auquel les banques se refinancent auprès de la banque centrale"],["Baisse des taux","Crédit moins cher, activité stimulée (relance)"],["Hausse des taux","Crédit plus cher, activité freinée (lutte contre l’inflation)"],["Stabilité des prix","Mission principale de la BCE : une inflation faible et maîtrisée"]]}]}],essentiel:["**Besoin** de financement (dépenses > ressources) vs **capacité** de financement (épargne) ; le système financier les met en relation.","Financement **interne** (autofinancement) vs **externe** ; externe = **direct** (marché) ou **indirect** (banque).","Financement **direct** sur le **marché financier** (Bourse) : **actions** (propriété, dividende) vs **obligations** (dette, intérêt).","Financement **indirect** = **crédit bancaire** (avec intérêts), le plus courant pour ménages et petites entreprises.","Les banques **créent de la monnaie** par le crédit (« les crédits font les dépôts ») ; excès → **inflation**.","La **BCE** pilote la politique monétaire via ses **taux directeurs** (baisse = relance, hausse = freine l’inflation) ; objectif : **stabilité des prix**."],resources:[{kind:"video",label:"Le financement de l’économie",note:"Vidéos — recherche YouTube",url:"https://www.youtube.com/results?search_query=financement%20direct%20indirect%20actions%20obligations%20banque%20premi%C3%A8re%20STMG%20%C3%A9conomie"}],games:[{id:"p1-eco-t4-qcm",type:"qcm",title:"QCM — Le financement",icon:"❓",questions:[{q:"Un agent qui épargne a une…",choices:["capacité de financement","besoin de financement","dette obligatoire","obligation légale"],answer:0,explain:"Capacité de financement = épargne disponible ; besoin = dépenses > ressources."},{q:"Emprunter auprès d’une banque est un financement…",choices:["indirect (intermédié)","direct","interne","gratuit"],answer:0,explain:"La banque est l’intermédiaire ; le marché financier = direct."},{q:"Une action est…",choices:["un titre de propriété d’une entreprise","un titre de dette","un crédit bancaire","un impôt"],answer:0,explain:"Action = part de propriété ; obligation = titre de dette."},{q:"La BCE agit sur l’économie via…",choices:["ses taux directeurs","la TVA","le SWOT","les cotisations"],answer:0,explain:"Baisser les taux stimule le crédit ; les monter freine l’inflation."}]},{id:"p1-eco-t4-tri",type:"tri",title:"Tri — Financement direct ou indirect ?",icon:"🗂️",instruction:"Classe chaque mode de financement.",categories:[{id:"dir",label:"Direct (marché)"},{id:"ind",label:"Indirect (banque)"}],items:[{text:"Émettre des actions en Bourse",cat:"dir"},{text:"Un crédit bancaire",cat:"ind"},{text:"Émettre des obligations",cat:"dir"},{text:"Un emprunt auprès de sa banque",cat:"ind"}]},{id:"p1-eco-t4-flash",type:"flashcard",title:"Flashcards — Financement",icon:"🃏",cards:[{front:"Besoin / capacité de financement",back:"Dépenser plus que gagner / épargner."},{front:"Financement direct",back:"Marché financier : actions et obligations."},{front:"Financement indirect",back:"Crédit accordé par une banque."},{front:"Taux directeurs (BCE)",back:"Outil pour stimuler l’économie ou freiner l’inflation."}]}]},{id:"p1-eco-t5",name:"Thème 5 — Les marchés sont-ils concurrentiels ?",short:"Le marché",keywords:"marché offre demande prix d’équilibre élasticité-prix coût marginal concurrence parfaite imparfaite monopole oligopole barrières à l’entrée",intro:"Un **marché** est le lieu de rencontre de l’**offre** et de la **demande**. De leur confrontation naît le **prix d’équilibre**. Mais la concurrence est souvent **imparfaite**.",cours:[{h:"Le marché : rencontre d’une offre et d’une demande",blocks:[{t:"p",c:"Un **marché** est le lieu (physique ou non) de **rencontre** entre une **offre** et une **demande**, où s’échange un bien ou un service à un **prix**. Il peut être très concret (un marché de fruits) ou totalement dématérialisé (le marché des actions, une plateforme en ligne)."},{t:"p",c:"Il existe des marchés de **biens et services**, du **travail**, des **capitaux**… Sur chacun, c’est la confrontation offre/demande qui détermine le **prix** et les **quantités** échangées."}]},{h:"L’offre et la demande",blocks:[{t:"p",c:"L’**offre** et la **demande** réagissent au **prix**, mais en sens **opposé** :"},{t:"p",c:"Quand le prix augmente, la **demande diminue** : certains acheteurs renoncent, car le produit leur paraît trop cher. Dans le même temps, l’**offre augmente** : produire devient plus rentable, donc les vendeurs proposent davantage."},{t:"p",c:"C’est la **loi de l’offre et de la demande** : la demande est **décroissante** avec le prix, l’offre est **croissante** avec le prix."},{t:"table",h:"Notions et définitions",head:["Notion","Définition"],rows:[["Demande","Quantité que les acheteurs souhaitent acheter ; décroissante avec le prix"],["Offre","Quantité que les vendeurs souhaitent vendre ; croissante avec le prix"],["Loi de l’offre et de la demande","La demande baisse et l’offre augmente quand le prix monte"]]}]},{h:"Le prix d’équilibre",blocks:[{t:"p",c:"Le **prix d’équilibre** est le prix pour lequel la **quantité offerte = la quantité demandée**. Le marché tend naturellement vers ce prix :"},{t:"list",c:["si le prix est **trop haut** : l’offre dépasse la demande → **surplus** → les prix baissent ;","si le prix est **trop bas** : la demande dépasse l’offre → **pénurie** → les prix montent."]},{t:"example",h:"Rareté et prix",c:`Une gelée détruit une partie de la récolte de fraises. 
→ L’**offre** chute alors que la **demande** reste forte : le **prix d’équilibre augmente**. Le prix joue son rôle de signal (la rareté se paie plus cher).`}]},{h:"L’élasticité-prix de la demande",blocks:[{t:"p",c:"L’**élasticité-prix de la demande** mesure la **sensibilité de la demande à une variation de prix** : « de combien la demande baisse-t-elle quand le prix augmente ? »"},{t:"p",c:"Une **demande élastique** est **très sensible au prix** : une hausse fait **beaucoup baisser** les achats. C’est le cas des **produits non essentiels** ou de ceux pour lesquels il existe des **substituts**."},{t:"p",c:"Une **demande peu élastique** est **peu sensible au prix** : même quand le prix monte, les achats **changent peu**. C’est le cas des **produits de première nécessité**, comme le pain, l’essence ou les médicaments."},{t:"p",c:"C’est une notion clé pour fixer les prix : sur un produit à demande **peu élastique**, une hausse de prix fait peu fuir les clients."},{t:"table",h:"Notions et définitions",head:["Notion","Définition"],rows:[["Élasticité-prix de la demande","Sensibilité de la demande à une variation de prix"],["Demande élastique","Très sensible au prix (produits non essentiels, avec substituts)"],["Demande peu élastique","Peu sensible au prix (pain, essence, médicaments)"],["Substitut","Produit qui peut en remplacer un autre"]]}]},{h:"Le coût marginal et la décision du producteur",blocks:[{t:"p",c:"Le **coût marginal** est le coût de production d’**une unité supplémentaire**. C’est un repère essentiel de la décision de produire."},{t:"p",c:"Le producteur a intérêt à produire **une unité de plus tant que son prix de vente couvre le coût marginal**. Au-delà, produire davantage lui coûterait plus que ça ne lui rapporte."}]},{h:"La concurrence pure et parfaite",blocks:[{t:"p",c:"La **concurrence pure et parfaite** est un **modèle théorique** qui suppose **cinq conditions** réunies :"},{t:"list",c:["**atomicité** : de très nombreux vendeurs et acheteurs, aucun assez gros pour influencer le prix ;","**homogénéité** : les produits sont **identiques** ;","**libre entrée et sortie** du marché ;","**transparence** : information parfaite de tous ;","**libre circulation** des facteurs de production."]},{t:"p",c:"Dans ce modèle, aucun acteur n’a de **pouvoir de marché** : tous « subissent » le prix. C’est un idéal théorique, rarement observé en réalité."}]},{h:"La concurrence imparfaite : monopole et oligopole",blocks:[{t:"p",c:"En pratique, la concurrence est souvent **imparfaite** : certains acteurs ont un **pouvoir de marché** (capacité à influencer le prix)."},{t:"p",c:"Dans un **monopole**, il n’y a qu’**un seul vendeur** : c’est le cas de la distribution d’eau dans une commune. Dans un **oligopole**, il y a **quelques vendeurs** seulement, comme dans la téléphonie mobile ou les carburants."},{t:"p",c:"Dans la **concurrence monopolistique**, les vendeurs sont **nombreux**, mais chacun propose un **produit différencié**, ce qui lui donne un petit pouvoir sur son prix : c’est le cas des restaurants ou des vêtements de marque."},{t:"p",c:"Moins il y a de vendeurs, plus ils ont de **pouvoir sur les prix** — au détriment, souvent, du consommateur."},{t:"table",h:"Notions et définitions",head:["Notion","Définition"],rows:[["Pouvoir de marché","Capacité à influencer le prix"],["Monopole","Un seul vendeur (distribution d’eau d’une commune)"],["Oligopole","Quelques vendeurs (téléphonie mobile, carburants)"],["Concurrence monopolistique","Beaucoup de vendeurs, produits différenciés (restaurants, marques)"]]}]},{h:"Barrières à l’entrée et asymétries d’information",blocks:[{t:"p",c:"Deux phénomènes expliquent que la concurrence reste imparfaite :"},{t:"list",c:["les **barrières à l’entrée** : obstacles qui empêchent de nouveaux concurrents d’arriver (coûts d’investissement très élevés, **brevets**, réglementation, notoriété d’une marque) — elles **protègent** les acteurs en place ;","les **asymétries d’information** : une partie en sait plus que l’autre (le vendeur d’une voiture d’occasion connaît mieux ses défauts que l’acheteur), ce qui fausse l’échange."]},{t:"p",c:"Pour préserver une concurrence saine, l’**État** (et l’**Autorité de la concurrence**) surveille et sanctionne les abus (ententes, abus de position dominante)."}]}],essentiel:["Un **marché** = rencontre d’une **offre** et d’une **demande** ; loi de l’offre et de la demande (demande décroissante, offre croissante avec le prix).","Le **prix d’équilibre** égalise quantité offerte et demandée (trop haut → surplus ; trop bas → pénurie).","**Élasticité-prix** = sensibilité de la demande au prix (élastique / peu élastique pour les biens de première nécessité).","**Coût marginal** = coût d’une unité supplémentaire ; on produit tant que le prix le couvre.","**Concurrence pure et parfaite** = 5 conditions (atomicité, homogénéité, libre entrée/sortie, transparence, mobilité) : un modèle théorique.","Concurrence **imparfaite** : **monopole**, **oligopole**, **barrières à l’entrée**, **asymétries d’information** → pouvoir de marché."],resources:[{kind:"video",label:"Marché, offre, demande, concurrence",note:"Vidéos — recherche YouTube",url:"https://www.youtube.com/results?search_query=march%C3%A9%20offre%20demande%20prix%20%C3%A9quilibre%20concurrence%20imparfaite%20premi%C3%A8re%20STMG"}],games:[{id:"p1-eco-t5-qcm",type:"qcm",title:"QCM — Le marché",icon:"❓",questions:[{q:"Le prix d’équilibre est celui pour lequel…",choices:["la quantité offerte = la quantité demandée","l’offre est nulle","la demande est infinie","le vendeur perd de l’argent"],answer:0,explain:"À l’équilibre, offre et demande s’égalisent."},{q:"Si un produit devient rare, son prix a tendance à…",choices:["augmenter","baisser","rester identique","disparaître"],answer:0,explain:"L’offre baisse alors que la demande reste forte → hausse du prix."},{q:"L’élasticité-prix de la demande mesure…",choices:["la sensibilité de la demande au prix","le coût d’une unité","le nombre de vendeurs","la marge"],answer:0,explain:"Forte sensibilité = demande élastique ; faible = peu élastique."},{q:"Un marché avec un seul vendeur est un…",choices:["monopole","oligopole","marché parfait","marché libre"],answer:0,explain:"Monopole = un vendeur ; oligopole = quelques-uns."},{q:"Les barrières à l’entrée…",choices:["freinent l’arrivée de nouveaux concurrents","garantissent la concurrence parfaite","baissent les prix","suppriment les monopoles"],answer:0,explain:"Coûts, brevets, réglementation protègent les acteurs en place."}]},{id:"p1-eco-t5-vf",type:"vraifaux",title:"Vrai / Faux rapide",icon:"⚡",questions:[{statement:"En concurrence pure et parfaite, les produits sont identiques.",answer:!0,explain:"Vrai : c’est l’une des hypothèses (homogénéité)."},{statement:"Un produit de première nécessité a une demande très élastique.",answer:!1,explain:"Faux : elle est peu élastique (on l’achète quel que soit le prix)."},{statement:"Le coût marginal est le coût d’une unité supplémentaire.",answer:!0,explain:"Vrai : on produit tant que le prix le couvre."}]},{id:"p1-eco-t5-flash",type:"flashcard",title:"Flashcards — Le marché",icon:"🃏",cards:[{front:"Prix d’équilibre",back:"Prix où quantité offerte = quantité demandée."},{front:"Élasticité-prix",back:"Sensibilité de la demande à une variation de prix."},{front:"Coût marginal",back:"Coût de production d’une unité supplémentaire."},{front:"Monopole / oligopole",back:"Un seul / quelques vendeurs (concurrence imparfaite)."}]}]}],m={id:e,name:t,short:n,icon:i,color:s,niveau:r,tagline:a,chapters:o},x=Object.freeze(Object.defineProperty({__proto__:null,chapters:o,color:s,default:m,icon:i,id:e,name:t,niveau:r,short:n,tagline:a},Symbol.toStringTag,{value:"Module"})),v={"p1-eco-t2":["La **valeur ajoutée** mesure la richesse **créée** : production − consommations intermédiaires (pas le chiffre d’affaires).","Croissance (variation du PIB) ≠ richesse totale (niveau du PIB) : ne confonds pas le flux et le stock."],"p1-eco-t5":["Sur un **marché**, le prix d’équilibre résulte de la rencontre offre/demande : ce n’est pas l’État qui le fixe (marché concurrentiel).","Élasticité de la demande : garde le **signe** et raisonne en **pourcentages**, pas en valeurs absolues."]},L=Object.freeze(Object.defineProperty({__proto__:null,default:v},Symbol.toStringTag,{value:"Module"}));export{g as a,q as b,f as c,b as d,h as e,x as m,L as p};
